/* Preserve TinyCC's pool size and reverse free-list initialization. */
enum {
	NEOCC_SYMBOLS_PER_BLOCK = 8192 / sizeof(struct neocc_symbol) ?
		8192 / sizeof(struct neocc_symbol) : 1
};

struct neocc_symbol_block {
	struct neocc_symbol_block *next;
	struct neocc_symbol symbols[NEOCC_SYMBOLS_PER_BLOCK];
};

static void symbols_clear(struct em_symbols *members)
{
	while (members->blocks) {
		struct neocc_symbol_block *block = members->blocks;

		members->blocks = block->next;
		free(block);
	}
	members->free_first = NULL;
}

static int symbols_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	return R_P;
}

static int symbols_close(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		symbols_clear(self->members);
	return R_P;
}

static int symbols_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	if (action != NEOCC_AC0_SYMBOLS_RESET) {
		SBO_OBJECT_INTERACT0;
	}
	if (!self->ref_count)
		return RN_INVALIDARG;
	symbols_clear(self->members);
	return R_P;
}

static int symbols_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_symbols *members = self->members;
	struct neocc_symbol *symbol;

	*output_quantity = 0;
	if (action != NEOCC_AC1_SYMBOLS_ALLOCATE) {
		SBO_OBJECT_INTERACT1;
	}
	if (!self->ref_count || capacity < sizeof(symbol))
		return RN_INVALIDARG;
	if (!members->free_first) {
		struct neocc_symbol_block *block = malloc(sizeof(*block));

		if (!block)
			return R_N;
		block->next = members->blocks;
		for (size_t i = 0; i < NEOCC_SYMBOLS_PER_BLOCK; i++) {
			block->symbols[i].next = members->free_first;
			members->free_first = &block->symbols[i];
		}
		members->blocks = block;
	}
	symbol = members->free_first;
	members->free_first = symbol->next;
	memcpy(output_stream, &symbol, sizeof(symbol));
	*output_quantity = sizeof(symbol);
	return R_P;
}

static int symbols_interact2(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	const struct vr *caller_context)
{
	struct em_symbols *members = self->members;
	struct neocc_symbol *symbol;

	if (action != NEOCC_AC2_SYMBOLS_RELEASE) {
		SBO_OBJECT_INTERACT2;
	}
	if (!self->ref_count || quantity != sizeof(symbol))
		return RN_INVALIDARG;
	memcpy(&symbol, input_stream, sizeof(symbol));
	if (!symbol)
		return RN_INVALIDARG;
	symbol->next = members->free_first;
	members->free_first = symbol;
	return R_P;
}

static int symbols_interact3(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	SBO_OBJECT_INTERACT3;
}

static int symbols_input(struct object *self, unsigned char *input_stream,
	unsigned int quantity, const struct vr *caller_context)
{
	SBO_OBJECT_INPUT;
}

static int symbols_output(struct object *self, unsigned char *output_stream,
	unsigned int capacity, unsigned int *output_quantity,
	const struct vr *caller_context)
{
	SBO_OBJECT_OUTPUT;
}

static int symbols_io_put(struct object *self, unsigned char *input_stream,
	unsigned int quantity, unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	SBO_OBJECT_IOPUT;
}

void tog_symbols(struct object *object)
{
	object->open = symbols_open;
	object->input = symbols_input;
	object->output = symbols_output;
	object->io_put = symbols_io_put;
	object->interact0 = symbols_interact0;
	object->interact1 = symbols_interact1;
	object->interact2 = symbols_interact2;
	object->interact3 = symbols_interact3;
	object->close = symbols_close;
}
